  return (
    <div className="notice-card">
      <h3>{title}</h3>
      <p>{content}</p>
      <button
        style={{
          padding: elderly ? "12px 24px" : undefined,
          fontSize: elderly ? "18px" : undefined
        }}
      >
        Read More
      </button>
    </div>
  );
}

export default NoticeCard;
